        /* Adattamenti per IE
        - * - - * - - * - - * - - * - - * - - * - - * - - * - - * - - * - */
        .ihn_photo{
            -ms-grid-row: 2;
            -ms-grid-row-span: 5;
            -ms-grid-column: 2;
        }
        .ih_news{
            display: -ms-grid;
            -ms-grid-columns: 8.34% 41.66% 50%;
            -ms-grid-rows: 45px 140px 92px 150px 150px auto;
        }
        .ihn_title_date {
            -ms-grid-row: 2;
            -ms-grid-column: 3;
        }
        .ihn_title {
            -ms-grid-row: 4;
            -ms-grid-column: 3;
        }
        .ihn_intro {
            -ms-grid-row: 5;
            -ms-grid-column: 3;
        }
        .ihn_read_more {
            -ms-grid-row: 6;
            -ms-grid-column: 3;
            -ms-grid-row-align: center;
            -ms-grid-column-align: center;
        }


.ihn_photo{ grid-area: Photo; width: 100%; background: #F0F2F4;  margin: 0;}
.ihn_photo img {max-width: 100%; height: auto;}

.ihn_title_date { grid-area: Title-Date; place-self: center; text-align: center; font-size: 18px; }
    .ihn_title_date h4{ margin: 0 0 10px 0; text-transform: uppercase; }
    .ihn_title_date p{ margin: 0; }
.ihn_title, .ihn_intro{
    grid-area: Title;
    padding: 0 15.3%;
    line-height: 1.2;
    text-transform: uppercase;
    text-align: center;
    place-self: center;
    overflow: hidden;
}
.ihn_title {font-size: 42px;}

.ihn_intro { grid-area: Intro; font-size: 22px; text-transform: initial; }
.ihn_read_more{ grid-area: Readmore; height: auto; font-size: 15px; place-self: center; }
.ih_news{
    display: grid;
    grid-template-columns: 8.34% 41.66% 50%;
    grid-template-rows: 45px auto 1px auto 150px auto;
    grid-template-areas: 
    ". . ."
    ". Photo Title-Date"
    ". Photo ."
    ". Photo Title"
    ". Photo Intro"
    ". Photo Readmore";
    background: #F0F2F4;
}


/* NEWS LIST
------------------------------------------------------------------------------------------ */
.news_list *{ position: relative; }
.news_list{ height: auto; margin: 120px 0 0 0; overflow: hidden; }
.news_list ul{
    width: 83.33%;
    height: auto;
    margin: 0 auto;
    display: flex;
    justify-content: left;
    flex-wrap: wrap;
    overflow: hidden;
}
    .news_list ul li{ width: 28.9%; height: auto; padding: 0 6.63% 120px 0; overflow: hidden; }
    .news_list ul li:nth-of-type(3n+3){ padding-right: 0; }
    .news_list ul li a{ display: block; }
    .news_list ul li figure{ width: 100%; height: 27.43vw; margin: 0; display: flex; }
    .news_list ul li img
    ,.news_list ul li source
    ,.news_list ul li picture
    { width: 100%; align-self: flex-end; }
    .news_list ul li h4 { margin: 15px 0 10px 0; font-size: 13px; text-transform: uppercase; line-height: 19px; }
    .news_list ul li p{margin: 0; font-size: 12px; color: #91A4B2; }




/* Schermi piccoli
========================================================================================== */
@media (max-width: 767px){


.ih_news{ grid-template-rows: 45px 140px auto 150px 150px 60px; }

.ih_news{
    grid-template-columns: 5% 90% 5%;
    grid-template-rows: 45px 140px auto auto auto 60px;
    grid-template-areas: 
    ". . ."
    ". Title-Date ."
    ". Title ."
    ". Photo ."
    ". Intro ."
    ". Readmore .";
}
.ihn_title{ padding: 30px 0;}
.ihn_intro { padding: 30px 0; margin: 0; }
.ihn_read_more{ padding: 30px 0; }


/* NEWS LIST
------------------------------------------------------------------------------------------ */
.news_list ul{ width: 90%; }
    .news_list ul li{ width: 48.5%; padding: 0 3% 100px 0; }
    .news_list ul li:nth-of-type(3n+3){ padding-right: 3%; }
    .news_list ul li:nth-of-type(2n+2){ padding-right: 0; }
    .news_list ul li figure{ height: 53.2vw; }



/* NEWS LIST
------------------------------------------------------------------------------------------ */
    .news_list ul li{ width: 100%; padding: 0 0 60px 0; }
    .news_list ul li:nth-of-type(3n+3){ padding-right: 0; }
    .news_list ul li:nth-of-type(2n+2){ padding-right: 0; }
    .news_list ul li figure{ height: auto; }

.ihn_read_more {padding-top: 0;}

} /* Schermi piccoli */

@media (max-width: 480px){
    .ihn_title{font-size: 9vw;}
}

